// (issue #238) A plain function may never take/return a raw ptr/T* type,
// even inside `unsafe { }` -- see checkNoRawPointersInSignature() -- so
// the original "pass null as a function argument" / "return null from a
// function" sub-cases below are no longer expressible through an ordinary
// function boundary (getNullNode()/processNode() used to do exactly
// that). Struct-field null-assignment covers the same underlying
// null-compatibility rule (typesCompatible()'s Rule 1, src/sema/Types.cpp)
// without needing a banned function signature.

import test;

unsafe {
    struct Node {
        val: int,
        next: Node*
    }
}

fn main(): int {
    // 1. Assign null to pointer type T*
    unsafe {
        mut p: Node* = null;
        test::assert(p == null, "p should be null");
    }

    // 2. Assign null to ptr
    unsafe {
        mut raw: ptr = null;
        test.assert(raw == null, "raw should be null");
    }

    // 3. Assign null to a raw-pointer-typed struct field
    unsafe {
        mut n: Node = Node::default();
        n.next = null;
        test::assert(n.next == null, "n.next should be null");
    }

    // 4. Compare ptr and void* to null
    unsafe {
        mut raw2: ptr = null;
        test::assert(null == raw2, "null comparison is symmetric");
    }

    return 0;
}

// Regression test: lib/std/mem.tr, imported and exercised end-to-end.
//
// Before this session, `import mem;` crashed the compiler outright (see
// tests/07_functions_modules/fail_import_syntax_error.tr and mem.tr's own
// doc comment for the two-part fix: `ptr` as a parameter name collided with
// this language's `ptr` type keyword, and a syntax error inside an
// imported module used to crash the whole compiler instead of failing
// cleanly). No test anywhere exercised this module at all, which is why
// the crash was never caught.

import mem;
import io;

import test;
// (issue #238) Every raw pointer local below needs `unsafe { }` around its
// declaration/cast (FINAL_SPRINT.md's Track A "Caller-side locals" rule)
// -- `mem::alloc`/`mem::zero`/etc. themselves stay ordinary, ungated calls
// (the entire `lib/std` tree is exempt from the gate).
fn main(): int {
    unsafe {
        // alloc / zero / free
        mut buf: void* = mem::alloc(32);
        test::assert(buf != null, "");
        mem::zero(buf, 32);

        // alloc_zeroed
        mut zbuf: void* = mem::alloc_zeroed(4, 8);
        test::assert(zbuf != null, "");

        // grow (realloc wrapper)
        mut grown: void* = mem::grow(buf, 64);
        test::assert(grown != null, "");

        // dup: copy bytes out of a fresh buffer and confirm it round-trips via
        // an int written into the source and read back out of the copy.
        mut src: int* = int(mem::alloc(8))*;
        src[0] = 12345;
        mut copy: int* = mem::dup(src, 8) to int*;
        test::assert(copy[0] == 12345, "");
        test::assert(copy != src, ""); // dup must return a genuinely distinct buffer

        mem::free(grown);
        mem::free(zbuf);
        mem::free(src);
        mem::free(copy);
    }

    io::printline("mem ok");
    return 0;
}

// Byte sizes computed during codegen use the target's data layout (found by
// turf-fuzz: `malloc(): corrupted top size` from safe code). The module got
// its layout only after codegen, so sizes came from LLVM's default layout,
// which aligns i64 to 4 bytes: `{bool, int, bool[4]}` was 16 bytes instead of
// 24. `.copy()` of an array of such structs then allocated too small a block
// and wrote past it, and `sizeof` (which sizes every List<T> buffer) was
// short the same way.

import test;
import list::List;

struct P { a: bool, n: int, b: bool[4] }

fn mk(n: int): P {
    mut p: P = P::default();
    p.n = n;
    p.b[3] = true;
    return p;
}

fn main(): int {
    test::assert(sizeof(P) == 24, "sizeof uses the target layout");

    mut arr: P[3] = [mk(1), mk(2), mk(3)];
    mut c: P[] = arr.copy();
    c[1].n = 50;
    test::assert(c[0].n == 1 && c[1].n == 50 && c[2].n == 3, "copy holds every element");
    test::assert(c[2].b[3], "including the trailing field");
    test::assert(arr[1].n == 2, "and is independent of the original");

    mut l: List<P> = List::default();
    mut i: int = 0;
    while i < 100 {
        l.push(mk(i));
        i += 1;
    }
    mut sum: int = 0;
    for (j in 0..100) {
        sum += l[j].n;
        test::assert(l[j].b[3], "every pushed element intact");
    }
    test::assert(sum == 4950, "a List of padded structs grows without overlap");
    return 0;
}

