// Regression test: declaring a variable from a field access chained directly
// off a function-call result (`mut p: int = makeBox().val;`) must actually
// register the variable and produce the correct value.
//
// Before the fix, FieldAccessExprAST::codegenLValue() had no r-value
// fallback for a non-addressable Base (like a FuncCallExprAST result) --
// unlike ArrayAccessExprAST::codegen() and MethodCallExprAST::codegen(),
// which both already handle this via "spill the r-value into a temp alloca,
// then GEP/pass that". It silently returned nullptr with NO diagnostic
// anywhere, which meant VarDeclExprAST::codegen() hit its
// `if (!Init) return nullptr;` early return WITHOUT ever calling
// GlobalSymbolTable->DeclareSymbol() -- so `p` was resolved fine by the
// Resolver (it has a VariableSymbol) but was never actually registered in
// Codegen's own symbol table. The only visible symptom was a confusing,
// wrong-cause error at the *next* use of `p`: "Hold on! You're trying to
// use 'p' before telling me what it is." -- nowhere near the real bug.
//
// See also tests/06_structs/16_struct_rvalue.tr, which exercises the same
// underlying codegen path (chained r-value field access) but via `test::assert()`
// directly on the call result rather than through an intermediate variable.

import io;

import test;
struct Box {
    val: int
}

func Box.new(val: int): void {
    self.val = val;
}

fn makeBox(): Box {
    return Box::new(42);
}

fn main(): int {
    mut p: int = makeBox().val;
    test::assert(p == 42, "");

    // Chained field access as a call argument (not just a bare statement)
    // must also actually execute and produce output -- this was the
    // clearest symptom before the fix: the containing statement compiled
    // clean but the printline call never ran at all.
    io::printline(p);

    return 0;
}

// Regression test (was DISCOVERED_ISSUES.md #16, "Missing Static
// Constructors"; migrated for the struct-construction overhaul -- see
// tests/06_structs/31_constructor_new.tr for the newer, primary coverage of
// this same mechanism). Originally exercised `fn StructName.init(args...)`,
// auto-detected by the (now-removed) StructInitExprAST::codegen() whenever a
// brace-literal's field VALUES happened to arity/type-match its params.
// That whole "guess whether this brace-literal wants the constructor" bridge
// is gone: `StructName.new(...)` is exactly the same idea (a '.'-declared
// method running arbitrary side effects via self) but reached only through
// the explicit `StructName::new(args...)` call form -- no implicit
// brace-literal-to-constructor matching left to get right or wrong.
//
// Kept as its own file (rather than folded into 31_constructor_new.tr) to
// preserve the ORIGINAL point being tested: a constructor can transform or
// validate its inputs instead of just copying them field-by-field, and a
// struct with NO constructor must still be constructible some other way
// (via `::default()` now, not an implicit fallback inside failed brace-init
// resolution).

import test;

struct Point {
    x: int,
    y: int
}

// Constructor that transforms its inputs rather than storing them verbatim.
fn Point.new(x: int, y: int): void {
    self.x = x * 10;
    self.y = y * 10;
}

struct Fraction {
    num: int,
    den: int
}

// A constructor that validates/normalizes -- rejects a zero denominator by
// substituting a sentinel, and always stores a positive denominator.
impl Fraction { fn new(n: int, d: int): void {
    if (d == 0) {
        self.num = 0;
        self.den = 1;
    } else if (d < 0) {
        self.num = 0 - n;
        self.den = 0 - d;
    } else {
        self.num = n;
        self.den = d;
    }
}

// A struct with NO custom constructor at all -- `::new(...)` isn't
// available for it (see fail_no_constructor_defined.tr); `::default()` is
// the only construction path.
struct Plain {
    a: int,
    b: int
}

fn main(): int {
    // Constructor transforms inputs (x*10, y*10).
    mut p: Point = Point::new(1, 2);
    test::assert(p.x == 10, "");
    test::assert(p.y == 20, "");

    // Constructor normalizes a negative denominator. Unlike the old
    // brace-literal form, arguments are now positional to the CONSTRUCTOR's
    // own declared parameter order (n, d) -- there's no struct field name
    // to match against at the call site at all.
    mut f: Fraction = Fraction::new(3, -4);
    test::assert(f.num == -3, "");
    test::assert(f.den == 4, "");

    // Constructor substitutes a sentinel for a zero denominator.
    mut bad: Fraction = Fraction::new(5, 0);
    test::assert(bad.num == 0, "");
    test::assert(bad.den == 1, "");

    // No constructor defined for Plain -- ::default() zero-inits, then
    // fields are set directly.
    mut pl: Plain = Plain::default();
    pl.a = 7;
    pl.b = 8;
    test::assert(pl.a == 7, "");
    test::assert(pl.b == 8, "");

    return 0;
}

// Regression test for the struct-construction overhaul: `StructName::new(...)`
// replaces the old ambiguous `StructName { field: val }` brace-literal (now
// removed from the parser entirely, along with the g_AllowStructInit flag it
// needed). A constructor is an ordinary '.'-declared instance method named
// "new" -- 'self' is auto-injected exactly like any other instance method --
// but can ONLY be invoked via `StructName::new(args...)`, never `x.new(...)`
// (see fail_dot_call_new.tr).
//
// Also covers: multiple fields set from constructor arguments in a
// different order than declared (constructor params are positional to the
// FUNCTION's own signature, not tied to field declaration order at all --
// unlike the old brace-literal form, which matched by field NAME).

import io;
import test;
extern fn strlen(s: string): int;

struct Point {
    x: int,
    y: int
}

// Params intentionally NOT in field-declaration order, to prove field
// values come from explicit `self.field = ...` assignments, not positional
// struct-field matching.
fn Point.new(y: int, x: int): void {
    self.x = x;
    self.y = y;
}

struct Rect {
    width: int,
    height: int,
    label: string
}

fn Rect.new(w: int, h: int, name: string): void {
    self.width = w;
    self.height = h;
    self.label = name;
}

fn main(): int {
    Point p = Point::new(20, 10);
    test::assert(p.x == 10, "x should be 10");
    test::assert(p.y == 20, "y should be 20");

    mut r: Rect = Rect::new(3, 4, "box");
    test::assert(r.width == 3, "width should be 3");
    test::assert(r.height == 4, "height should be 4");
    test::assert(strlen(r.label) == 3, "label should be 'box'");

    io::printline("constructor new() works");
    return 0;
}

