// Test: Point::default() + setting only SOME fields afterward -- the
// replacement for the old partial-field brace-literal (`Point{x: 5}`,
// leaving y/z at their defaults), which no longer parses at all.
import io;

import test;
struct Point {
    x: int,
    y: int,
    z: int
}

fn main(): int {
    mut p: Point = Point{};
    p.x = 5;
    test::assert(p.x == 5, "explicit x=5");
    test::assert(p.y == 0, "missing y defaults to 0");
    test::assert(p.z == 0, "missing z defaults to 0");

