// tests/13_string_stdlib/26_str_building_is_linear.tr
// LEC-007: repeat / replace / join were all `result = result + piece` loops,
// i.e. O(n^2): every pass re-copied the whole accumulated string.
//
// The repeat size is the one that carries the timing assertion. Measured
// 2026-10-01 with the old loop shape (`result = result + "ab"`): 200,000
// pieces took 1.9 s and 600,000 took 23 s, against the runner's 5 s
// per-test limit (TURF_TEST_TIMEOUT_SEC) -- so a regression back to
// concatenation fails here as a TIMEOUT, while the builder takes
// milliseconds. The replace/join sizes are not calibrated that way; they are
// content checks at a size where an off-by-one in the buffer growth shows up.

import strings;
import list::List;
import test;

fn main(): int {
    // repeat: 600,000 x "ab" = 1,200,000 bytes.
    let r: string = strings::repeat("ab", 600000);
    test::assert(strings::length(r) == 1200000, "repeat length");
    test::assert(strings::starts_with(r, "abab"), "repeat start");
    test::assert(strings::ends_with(r, "abab"), "repeat end");
    test::assert(strings::repeat("x", 0) == "", "repeat 0 -> \"\"");
    test::assert(strings::repeat("x", -3) == "", "repeat negative -> \"\"");
    test::assert(strings::repeat("", 1000) == "", "repeat of \"\" -> \"\"");

    // replace: 20,000 matches in a 100,000-byte string, changing the length.
    immut src: string = strings::repeat("a,b,c,d,e,", 10000);
    immut swapped: string = strings::replace(src, ",", "::");
    test::assert(strings::length(src) == 100000, "source length");
    test::assert(strings::length(swapped) == 100000 + 50000, "each of 50,000 commas grew by 1 byte");
    test::assert(strings::starts_with(swapped, "a::b::c::d::e::a::"), "replace start");
    test::assert(strings::count_char(swapped, 44) == 0, "no comma survived");
    // Deleting every match shrinks it back to the letters.
    test::assert(strings::length(strings::replace(src, ",", "")) == 50000, "replace with \"\"");

    // join: 20,000 items.
    mut items: List<string> = List::default();
    mut i: int = 0;
    while i < 20000 {
        items.push("item");
        i = i + 1;
    }
    immut joined: string = strings::join(items, ", ");
    test::assert(strings::length(joined) == 20000 * 4 + 19999 * 2, "join length");
    test::assert(strings::starts_with(joined, "item, item, item"), "join start");
    test::assert(strings::ends_with(joined, ", item"), "join end has no trailing separator");

    return 0;
}

// Regression test (Issue #180): `do { } while(true)` with a body that has no
// break, continue, or return must trigger an InfiniteLoopWarning (from
// Lint.cpp's LintDoWhile) but still compile successfully (TurfWarning never
// interrupts compilation) -- mirrors 03_infinite_while_true_warns.tr but for
// the do-while sibling construct.
//
// This test intentionally never reaches the do-while loop at runtime --
// returning early via `if true { return 0; }` -- so the test suite does not
// actually hang.

fn main(): int {
    mut x: int = 0;
    if true {
        return 0;

    do {
        x = x + 1;
    } while (true);
    return 0;
}

// Regression test (Issue #180): `x != true` / `x == true` style stale
// conditions inside a do-while's `while (cond)` clause must trigger
// RedundantComparisonWarning, same as they do for a plain `while` condition
// (Lint.cpp's LintBinaryExpr is generic over the parent statement, but it
// only ever runs if LintExpression actually recurses into the condition --
// which requires LintDoWhile to exist and be dispatched to).

use test;

fn main(): int {
    mut ok: bool = false;
    mut iterations: int = 0;
    do {
        iterations = iterations + 1;
        ok = true;
    } while (ok != true);
    test::assert(iterations == 1, "");

    mut finished: bool = false;
    mut count: int = 0;
    do {
        count = count + 1;
        finished = true;
    } while (finished == false);
    test::assert(count == 1, "");

    return 0;
}

// Regression test (Issue #180 follow-up): a `do { } while(true)` with no
// break/return, nested inside an ordinary (finite, breakable) `for` loop.
// Cross-type nesting check: the outer `for` is completely unrelated to the
// do-while's own unbreakable cycle, so CFGBuilder::visitDoWhile() must still
// correctly close the do-while's own cond->body edge (no cond->exit edge for
// a literal-true condition) regardless of what kind of loop encloses it --
// the do-while itself must be flagged unbreakable.
//
// Intentionally returns before ever reaching the loop so the test suite
// doesn't actually hang (same technique as 28_infinite_do_while_true_warns.tr).

fn main(): int {
    if true {
        return 0;
    }
    mut total: int = 0;
    for (int i = 0; i < 3; i++) {
        mut x: int = 0;
        do {
            x = x + 1;
            total = total + x;
        } while (true);
    }
    return 0;
}

// EXPECT-NO-DIAG: dead store
// EXPECT-NO-DIAG: is never read
// EXPECT-NO-DIAG: never used
// Writing one element keeps the others, so it does not end the life of the
// value stored before it: neither `x[0] = 1` nor `y`'s initializer is dead.

import test;

fn main(): int {
    mut x: int[3];
    x[0] = 1;
    x[1] = 2;
    test::assert(x[0] == 1 && x[1] == 2 && x[2] == 0, "both writes are read");

    mut y: int[3] = {4, 5, 6};
    y[2] = 9;
    test::assert(y[0] == 4 && y[2] == 9, "the initializer is read");

    mut grid: int[2][2] = [[1, 2], [3, 4]];
    mut i: int = 0;
    while i < 2 {
        grid[i][i] = 0;
        i = i + 1;
    }
    test::assert(grid[0][1] == 2 && grid[1][1] == 0, "a loop writing elements");
    return 0;
}

// Test: Enum-to-int and int-to-enum casting
import test;

enum Weekday { Mon, Tue, Wed, Thu, Fri, Sat, Sun }

fn main(): int {
    // Enum -> int: each variant returns its ordinal
    test::assert((Weekday::Mon to int) == 0, "Mon == 0");
    test::assert((Weekday::Tue to int) == 1, "Tue == 1");
    test::assert((Weekday::Wed to int) == 2, "Wed == 2");
    test::assert((Weekday::Thu to int) == 3, "Thu == 3");
    test::assert((Weekday::Fri to int) == 4, "Fri == 4");
    test::assert((Weekday::Sat to int) == 5, "Sat == 5");
    test::assert((Weekday::Sun to int) == 6, "Sun == 6");

    // int -> enum: cast integer back and compare
    immut mon: Weekday = 0 to Weekday;
    immut fri: Weekday = 4 to Weekday;
    immut sun: Weekday = 6 to Weekday;

    test::assert(mon == Weekday::Mon, "0 to Weekday == Mon");
    test::assert(fri == Weekday::Fri, "4 to Weekday == Fri";
    test::assert(sun == Weekday::Sun, "6 to Weekday == Sun");

    // Round-trip: enum -> int -> enum
    immut w: Weekday = Weekday::Wed;
    immut wInt: int = w to int;
    immut wBack: Weekday = wInt to Weekday;
    test::assert(wBack == Weekday::Wed, "Round-trip Wed -> 2 -> Wed");
    return 0;
}

// Enum, state machine and `error` types declared INSIDE a function body --
// including an enum inside a generic function, cloned per instantiation.
// All three parsed fine but were never registered: Pass 1 only hoists
// top-level declarations, and the Resolver's visitors for these three
// kinds were no-ops ("Pass 1 already hoisted it"), so a local
// `enum Sign {...}`'s own `Sign::Neg` failed as "'Sign' isn't a known
// enum, struct, or module". They are now registered where they are
// declared, like a local struct.

import test;

fn classify(n: int): int {
    enum Sign { Neg, Zero, Pos }
    mut s: Sign = Sign::Zero;
    if (n < 0) { s = Sign::Neg; }
    if (n > 0) { s = Sign::Pos; }
    compare s {
        case Sign::Neg:
        return -1;
        done
        matches Sign::Zero:
        return 0;
        done
        matches Sign::Pos:
        return 1;
        done
    }
    return 99;
}

fn<T> kindOf(v: T): int {
    enum Kind { One, Two }
    return Kind::Two to int;
}

fn doorState(): int {
    machine Door { Open -> Shut, Shut -> Open }
    mut d: Door = Door::Open;
    return d to int;
}

fn checked(n: int): !int {
    error Bad { Negative, Huge }
    if (n < 0) { return Bad::Negative; }
    if (n > 100) { return Bad::Huge; }
    return n;
}

fn failureCode(n: int): int {
    mut v: int = checked(n) recover as err run {
        return 1;
    };
    return v;
}

fn main(): int {
    test::assert(classify(-5) == -1, "local enum, compare");
    test::assert(classify(3) == 1, "local enum, other arm");
    test::assert(kindOf(1) == 1 && kindOf("x") == 1, "local enum in a generic fn, two instantiations");
    test::assert(doorState() == 0, "local machine");

    mut ok: int = checked(5) recover produce -1;
    mut bad: int = checked(-5) recover produce -1;
    test::assert(ok == 5, "local error type, success path");
    test::assert(bad == -1, "local error type, recovered");
    test::assert(failureCode(500) == 1, "recover as err with a local error type");
    return 0;
}

