// lib/std/bool.tr's UFCS helpers. All prelude, no import needed.

import test;

fn main(): int {
    mut t: bool = true;
    bool f = false;

    test::assert(t.logical_xor(f), "true xor false == true");
    test::assert(!t.logical_xor(t), "true xor true == false");

    test::assert(!t.logical_nand(t), "true nand true == false");
    test::assert(f.logical_nand(f), "false nand false == true");

    test::assert(f.logical_nor(f), "false nor false == true");
    test::assert(!t.logical_nor(f), "true nor false == false");

    test::assert(f.implies(f), "false implies false == true");
    test::assert(f.implies(t), "false implies true == true");
    test::assert(!t.implies(f), "true implies false == false");
    test::assert(t.implies(t), "true implies true == true");

    return 0;
}

// Regression test: a struct success type (`!Point`, not just primitives)
// must round-trip correctly through FallibleValue's boxed successBits slot.
// A single-field `{x: int}` struct is still a real LLVM struct, not a bare
// i64 -- found live while converting net.tr's TcpConnection::connect() to
// `!T` (the struct's fields were silently truncated to zero before
// BoxToI64Slot()/UnboxFromI64Slot() learned to heap-box non-scalar values).
import test;

error MyError {
    Failed,
}

struct Point {
    x: int,
    y: int,
}

def Point.new(x: int, y: int): void {
    self.x = x;
    self.y = y;
}

fn makePoint(shouldFail: bool): !Point {
    if (shouldFail) {
        return MyError::Failed;
    }
    return Point::new(42, 7);
