// LEC-004: a value of a DECLARED error type (not just the open `err`) can be
// destructured too, and -- since its variants are listable -- a compare that
// covers every variant with a variant pattern whose fields all match anything
// is exhaustive WITHOUT `otherwise`.
import io;
import test;

error IOError {
    NotFound(path: string),
    Denied(path: string, mode: int),
    Timeout
}

fn weight(e: IOError): int {
    match e {
        matches IOError::NotFound(_path):
        return 1;
        done
        matches IOError::Denied(_, mode):
        return 10 + mode;
        done
        matches IOError::Timeout:
        return 100;
        done
    }
}

fn weightWithCatchAll(e: IOError): int {
    compare e {
        matches IOError::Denied(_, 3):
        return 3;
        done
        otherwise:
        return 0;
    }
}

fn main(): int {
    mut a: IOError = IOError::NotFound("x");
    mut b: IOError = IOError::Denied("y", 4);
    mut c: IOError = IOError::Timeout;
    test::assert(weight(a) == 1, "NotFound");
    test::assert(weight(b) == 14, "Denied binds mode");
    test::assert(weight(c) == 100, "Timeout");
    test::assert(weightWithCatchAll(IOError::Denied("z", 3)) == 3, "a refutable payload pattern matches");
    test::assert(weightWithCatchAll(IOError::Denied("z", 2)) == 0, "and falls to otherwise when it fails");
    io::printline("25/20 PASS");
    return 0;
}

// LEC-004: `try` on a `!void` is a statement: nothing to unbox, only the error
// to pass on.
import io;
import test;

error IoError {
    Closed(fd: int)
}

fn write(fd: int): !void {
    if fd < 0 { return IoError::Closed(fd); }
    return;
}

fn writeBoth(a: int, b: int): !void {
    try write(a);
    try write(b);
    return;
}

fn outcome(a: int, b: int): int {
    writeBoth(a, b) recover as err run {
        compare err {
            matches IoError::Closed(f):
            return f;
            break;
            otherwise:
            return 99;
        }
    };
    return 0;
}

fn main(): int {
    test::assert(outcome(5, 6) == 0, "both writes succeed");
    test::assert(outcome(0 - 4, 6) == 0 - 4, "the first write fails and leaves");
    test::assert(outcome(5, 0 - 7) == 0 - 7, "the second write fails after the first succeeded");
    test::assert(outcome(0 - 4, 0 - 7) == 0 - 4, "the first error wins: the second write never runs");
    io::printline("25/26 PASS");
    return 0;
}

// LEC-007: io::write_string returns `!void` and fails with
// FileError::WriteFailed(path) -- it returned a bare bool before, while the
// read functions on the same file already reported `!T` carrying the path.
// The failure is real (a directory that does not exist), and WriteFailed is
// told apart from the read-side variants.
import io;
import test;

fn write_failure_path(path: string): string {
    io::write_string(path, "data") recover as err run {
        compare err {
            matches io::FileError::WriteFailed(p):
            return p;
            done
            default:
            return "wrong variant";
        }
    };
    return "";
}

fn main(): int {
    immut bad: string = "/definitely/not/a/dir/out.txt";
    test::assert(write_failure_path(bad) == bad, "WriteFailed carries the path that could not be written");
    test::assert(!io::exists(bad), "and nothing was created");
    return 0;
}

// Coverage for time::clock_ticks()/time::elapsed_ms()/time::elapsed_seconds()
// against real CPU-bound work (a busy loop), which is what clock() actually
// measures -- see time.tr's design note on why this is CPU time, not
// wall-clock time. Also pins CLOCKS_PER_SEC's real, empirically-confirmed
// value (see time.tr's own doc comment).
import time;
import test;
import io;

fn main(): int {
    test::assert_eq(time::CLOCKS_PER_SEC, 1000000, "CLOCKS_PER_SEC must be glibc/Linux's real value");

    immut start: int = time::clock_ticks();

    // A large, genuinely CPU-bound busy loop -- no I/O, no sleeping, so
    // clock() should advance close to 1:1 with real time spent here.
    //
    // OPT-001: this loop's body has no effect the OPTIMIZER can see once a
    // real -O2 pipeline runs (`i`'s final value is never read), and a real
    // -O2 pipeline includes loop-deletion/IndVarSimplify -- which a plain
    // "count to N and discard the counter" loop is exactly the textbook
    // input for. Confirmed live while implementing OPT-001: at the old
    // 5-pass ad hoc pipeline (mem2reg/instcombine/reassociate/GVN/
    // simplifycfg -- none of which include loop deletion) this loop
    // survived by accident, not by design; under the real default pipeline
    // it was removed entirely, so `elapsed_ms()` read back ~0 and this
    // assertion failed. The periodic call below is a genuine external
    // (`extern fn clock()`, unannotated -- LLVM cannot assume it is
    // side-effect-free) side effect once every 1000 iterations, which is
    // enough to make the WHOLE loop's execution observable and therefore
    // impossible to delete, while adding negligible wall-clock overhead
    // (500,000 cheap `clock()` reads, not 500,000,000).
    mut i: int = 0;
    while i < 500000000 {
        i = i + 1;
        if i % 1000 == 0 {
            time::clock_ticks();
        }
    }

    immut ms: int = time::elapsed_ms(start);
    immut seconds: int = time::elapsed_seconds(start);

    // Generous band: this loop takes on the order of tens to a few hundred
    // milliseconds on typical hardware, but must be strictly positive (real
    // CPU work happened) and not implausibly large (e.g. a units bug that
    // reports seconds as if they were milliseconds by 1000x).
    test::assert(ms > 0, "elapsed_ms() must be positive after real CPU-bound work");
    test::assert(ms < 30000, "elapsed_ms() should stay well under 30s for this loop -- guards against a units/scale bug");
    test::assert(seconds >= 0 && seconds <= 30, "elapsed_seconds() should be consistent with elapsed_ms()'s band");
    test::assert_eq(seconds, ms / 1000, "elapsed_seconds() must equal elapsed_ms() / 1000");

    println("03 PASS: time::clock_ticks / elapsed_ms / elapsed_seconds track real CPU-bound work");
    return 0;
}

// Regression coverage for the new `random` stdlib module:
