// A standard library failure carries a message saying what failed, besides
// its payload. Every one was built with no message, so a handler printing
// `err.message` printed a blank line.

import test;
import fs;
import json;
import map::Map;

fn fs_message(): string {
    mut m: string = "";
    fs::mkdir("/nonexistent_turf_dir/sub") recover as err run { m = err.message; };
    return m;
}

fn io_message(): string {
    immut s: string = io::read_to_string("/nonexistent_turf_dir/f.txt") recover as err run {
        return err.message;
    };
    return "read " + s;
}

fn parse_message(): string {
    immut n: int = strings::parse_int("x1") recover as err run { return err.message; };
    return n to string;
}

fn divide_message(): string {
    immut q: int = math::divide(1, 0) recover as err run { return err.message; };
    return q to string;
}

fn map_message(): string {
    mut m: Map<string, int> = Map::default();
    auto v = m.try_get("k") recover as err run { return err.message; };
    return v to string;
}

fn json_message(): string {
    immut j: json::JsonValue = json::parse("[1,") recover as err run { return err.message; };
    return typeof(j);
}

fn main(): int {
    test::assert(fs_message() == "could not create directory '/nonexistent_turf_dir/sub'", "fs");
    test::assert(io_message() == "file not found: '/nonexistent_turf_dir/f.txt'", "io");
    test::assert(parse_message() == "not an int: 'x1'", "strings");
    test::assert(divide_message() == "division by zero", "math");
    test::assert(map_message() == "key not found", "map");
    test::assert(json_message() == "unexpected end of JSON at offset 3", "json");
    return 0;
}

// Regression test: lib/std/collections/set.tr (Set<T>), imported and
// exercised end-to-end -- add/contains/remove/length, duplicate-add being
// a no-op, and growth past the initial capacity.
import set::Set;
import test;

fn main(): int {
    mut s: Set<int> = Set::default();
    test::assert(s.length() == 0, "new set starts empty");

    s.add(1);
    s.add(2);
    s.add(3);
    test::assert(s.size() == 3, "three distinct adds should give length 3");
    test::assert(s.contains(1) == true, "");
    test::assert(s.contains(2) == true, "");
    test::assert(s.contains(3) == true, "");
    test::assert(s.contains(4) == false, "not-added item should not be contained");

    // Duplicate add must be a no-op (no length change, no growth).
    s.add(2);
    test::assert(s.length() == 3, "adding an already-present item must be a no-op");

    // remove() reports whether it actually removed something.
    immutable removedExisting: bool = s.remove(2);
    test::assert(removedExisting == true, "removing a present item returns true");
    test::assert(s.length() == 2, "length drops after a real removal");
    test::assert(s.contains(2) == false, "removed item is no longer contained");

    immutable removedMissing: bool = s.remove(999);
    test::assert(removedMissing == false, "removing an absent item returns false");
    test::assert(s.length() == 2, "removing an absent item must not change length");

    // Force growth past the initial capacity (8).
    mut big: Set<int> = Set::default();
    mut i: int = 0;
    while i < 20 {
        big.add(i);
        i = i + 1;
    }
    test::assert(big.length() == 20, "20 distinct adds should give length 20");
    // Re-adding everything again must not grow the set further.
    i = 0;
    while i < 20 {
        big.add(i);
        i = i + 1;
    }
    test::assert(big.length() == 20, "re-adding existing items must not change length");

    return 0;
}

