// Regression test (OVH-003, docs/planning/OVERHAUL_REMAINING_WORK.md):
// `List<T>.get(i)`/`.set(i, value)` -- the bounds-checked, GENUINELY
// generic replacement for reading/writing an element via the raw `data:
// T*` field directly (`l.data[i]`, now gated outside `unsafe { }` -- see
// tests/05_arrays_pointers_ffi/fail_raw_pointer_index_outside_unsafe.tr).
// Unlike `operator[]`/`operator[]=` (LANG-001), which are declared for
// the concrete `List<int>` only, `get`/`set` work for any `T` -- covered
// here across a primitive (`int`), a GC-heap pointer type (`string`), and
// a genuine multi-field by-value struct (`Triple`, 24 bytes -- three
// int64 fields, exercising the >8-byte-struct-by-value path TYPE-002
// made possible).

import list::List;
import test;

struct Triple {
    a: int,
    b: int,
    int c;
}

fn main(): int {
    // int
    mut li: List<int> = List::default();
    li.push(10);
    li.push(20);
    li.push(30);
    test::assert(li.get(0) == 10 && li.get(1) == 20 && li.get(2) == 30,
        "List<int>.get reads pushed values");
    li.set(1, 99);
    test::assert(li.get(1) == 99, "List<int>.set overwrites in place");

    // string (a GC-heap pointer element type)
    mut ls: List<string> = List::default();
    ls.push("alpha");
    ls.push("beta");
    test::assert(ls.get(0) == "alpha" && ls.get(1) == "beta",
        "List<string>.get reads pushed values");
    ls.set(0, "gamma");
    test::assert(ls.get(0) == "gamma", "List<string>.set overwrites in place");

    // a genuine multi-field by-value struct, 24 bytes
    mut lt: List<Triple> = List::default();
    mut t1: Triple = Triple::default();
    t1.a = 1; t1.b = 2; t1.c = 3;
    lt.push(t1);
    test::assert(lt.get(0).a == 1 && lt.get(0).b == 2 && lt.get(0).c == 3,
        "List<Triple>.get reads all three fields correctly");
    mut t2: Triple = Triple::default();
    t2.a = 7; t2.b = 8; t2.c = 9;
    lt.set(0, t2);
    test::assert(lt.get(0).a == 7 && lt.get(0).b == 8 && lt.get(0).c == 9,
        "List<Triple>.set overwrites the whole struct in place");

    return 0;
}

// LEC-007: Map.keys() / Map.values(). Map's storage is private (LEC-002), which
// left no way to enumerate a map. They return copies in dense-array order and
// keys()[i] pairs with values()[i].
import map::Map;
import list::List;
import test;

struct Big {
    a: int,
    b: int,
    c: int
}

fn main(): string {
    // Empty map: empty lists, and no allocation trouble.
    mut empty: Map<string, int> = Map::default();
    test::assert(empty.keys().length() == 0, "empty map has no keys");
    test::assert(empty.values().length() == 0, "empty map has no values");

    mut m: Map<string, int> = Map::default();
    m.put("one", 1);
    m.put("two", 2);
    m.put("three", 3);

    // Insertion order while nothing has been removed.
    immut ks: List<string> = m.keys();
    immut vs: List<int> = m.values();
    test::assert(ks.length() == 3 && vs.length() == 3, "three entries each");
    test::assert(ks.get(0) == "one" && ks.get(1) == "two" && ks.get(2) == "three", "keys in insertion order");
    test::assert(vs.get(0) == 1 && vs.get(1) == 2 && vs.get(2) == 3, "values in insertion order");

    // keys()[i] belongs to values()[i].
    mut i: int = 0;
    while i < ks.length() {
        test::assert(m.get(ks.get(i)) == vs.get(i), "keys()[i] pairs with values()[i]");
        i = i + 1;
    }

    // A copy: changing the map afterwards does not change an earlier result.
    m.put("four", 4);
    m.put("one", 100);
    test::assert(ks.length() == 3, "an earlier keys() result keeps its length");
    test::assert(vs.get(0) == 1, "and its values");
    test::assert(m.keys().length() == 4, "a fresh keys() sees the new entry");

    // After remove() the order is swap-with-last (documented), but the SET of
    // keys is exact and the pairing still holds.
    m.remove("two");
    immut ks2: List<string> = m.keys();
    immut vs2: List<int> = m.values();
    test::assert(ks2.length() == 3, "one fewer key after remove");
    mut j: int = 0;
    mut saw_two: bool = false;
    while j < ks2.length() {
        if ks2.get(j) == "two" {
            saw_two = true;
        }
        test::assert(m.get(ks2.get(j)) == vs2.get(j), "pairing survives remove()");
        j = j + 1;
    }
    test::assert(!saw_two, "the removed key is gone from keys()");

    // A value type over 8 bytes: copied by value, not truncated to a word.
    mut bigs: Map<int, Big> = Map::default();
    mut b1: Big = Big::default();
    b1.a = 1;
    b1.b = 2;
    b1.c = 3;
    mut b2: Big = Big::default();
    b2.a = 10;
    b2.b = 20;
    b2.c = 30;
    bigs.put(7, b1);
    bigs.put(8, b2);
    immut bv: List<Big> = bigs.values();
    test::assert(bv.get(0).c == 3 && bv.get(1).a == 10 && bv.get(1).c == 30, "struct values over 8 bytes survive values()");
    immut bk: List<int> = bigs.keys();
    test::assert(bk.get(0) == 7 && bk.get(1) == 8, "int keys");

    return 0;
}

// A Map and a Set under steady churn: a sliding window of keys, each step one
// insert and one remove, so the size stays put while tens of thousands of
// entries come and go. Tombstones now count toward the rebuild check, and a
// rebuild at the same size clears them. Before, they filled every empty slot
// and every lookup of a missing key probed the whole table (found by REL-005's
// benchmarks; the cost grew with the table). This checks the answers stay
// right through those rebuilds; bench/map_churn.tr tracks the speed.

import test;
use map::Map;
import set::Set;

fn main(): int {
    immut window: int = 300;
    immut steps: int = 30000;
    mut m: Map<int, int> = Map::default();
    mut s: Set<int> = Set::default();
    for i in 0..steps {
        m.put(i, i * 2);
        s.add(i);
        if (i >= window) {
            m.remove(i - window);
            test::assert(s.remove(i - window), "the set held the key leaving the window");
            test::assert(!m.contains(i - window), "a removed key is gone");
            test::assert(m.get(i - window + 1) == (i - window + 1) * 2, "the oldest live key is found");
            test::assert(s.contains(i), "the newest set key is found");
        }
        test::assert(m.length() == s.length(), "map and set agree on size");
    }
    test::assert(m.length() == window, "the map holds exactly the window");
    mut sum: int = 0;
    for k in (steps - window)..steps {
        sum = sum + m.get(k);
    }
    test::assert(sum == window * (2 * steps - window - 1), "every live key maps to its value");
    test::assert(!s.contains(steps - window - 1), "nothing older survived");
    return 0;
}

