// Map and Set keys that `==` calls equal are the same key. hashing::hash()
// used to hash a value's raw bytes, which broke that in three ways (found
// reviewing Map/Set for REL-005): a struct's padding holds leftover bytes, so
// equal struct keys hashed apart (at -O0, 1999 of 2000 lookups missed; at -O2
// none, a level-dependent answer); -0.0 == 0.0 but their bytes differ; and a
// struct whose fields are strings was hashed by the string pointers, not
// their text. It now uses hash_of() (owner decision 2026-10-13), which hashes
// field by field. Run at -O0 too: that is where the padding showed.

import test;
import map::Map;
import set::Set;

struct P {
    c: char,
    n: int
}

operator ==(x: P, y: P): bool {
    return x.c == y.c && x.n == y.n;
}

struct Person {
    name: string,
    age: int
}

operator ==(x: Person, y: Person): bool {
    return x.name == y.name && x.age == y.age;
}

// Leaves non-zero bytes where the next frame's padding will be.
fn dirty(seed: int): int {
    mut a: int[64];
    a[0] = seed;
    for (i in 0..64) {
        a[i] = -1 - i * seed;
    }
    return a[63];
}

fn mk(n: int): P {
    mut p: P = P::default();
    p.c = 'a';
    p.n = n;
    return p;
}

fn person(n: int): Person {
    mut p: Person = Person::default();
    p.name = "p" + (n to string);
    p.age = n;
    return p;
}

fn id(x: double): double {
    return x;
}

fn main(): int {
    mut s: Set<P> = Set::default();
    for i in 0..2000 {
        s.add(mk(i));
    }
    mut missing: int = 0;
    for i in 0..2000 {
        if (!s.contains(mk(i)) && dirty(i + 7) != 12345) {
            missing += 1;
        }
    }
    test::assert(missing == 0, "every padded struct key is found again");

    mut m: Map<double, int> = Map::default();
    mut d: Set<double> = Set::default();
    for i in 1..1001 {
        m.put(i to double, i);
        d.add(i to double);
    }
    immut negz: double = id(0.0) * id(-1.0);
    m.put(id(0.0), 0);
    d.add(id(0.0));
    d.add(negz);
    test::assert(m.contains(negz), "-0.0 finds the 0.0 key");
    test::assert(d.length() == 1001, "0.0 and -0.0 are one set member");

    mut people: Map<Person, int> = Map::default();
    for i in 0..500 {
        people.put(person(i), i);
    }
    mut found: int = 0;
    for i in 0..500 {
        if (people.contains(person(i))) {
            found += 1;
        }
    }
    test::assert(found == 500, "a struct key with a string field matches by text");
    test::assert(people.get(person(42)) == 42, "and maps to its value");
    return 0;
}

# A JSON number may have an exponent (RFC 8259: `1e10`, `2.5E-3`,
// `-1.5e+2`), and json::stringify writes one for a large or small number
// (`%g`: 1e+21, 1e-06). json::parse failed on every such number, so a value
// json::stringify wrote could not be read back: strings::parse_double
// rejected exponents (the header claimed only the value came out wrong).

import json;
import test;

// A `return` inside `recover run` returns from the enclosing function, so the
// failure check lives in its own helper.
fn rejects(text: string): bool {
    immut v: json::JsonValue = json::parse(text) recover run {
        return true;
    };
    return v.length() < 0;
}

fn main(): int {
    immut v: json::JsonValue = json::parse("[3e2, -1.5E-3, 1e+21, 2, 0.5e1]") recover run {
        test::fail("numbers with exponents are valid JSON");
        return 1;
    };
    test::assert_eq(v.length(), 5, "five numbers");
    test::assert_eq(v.at(0).num_val, 300.0, "3e2");
    test::assert_eq(v.at(1).num_val, -0.0015, "-1.5E-3");
    test::assert_eq(v.at(2).num_val, 1e21, "1e+21");
    test::assert_eq(v.at(4).num_val, 5.0, "0.5e1");

    // What stringify writes with an exponent reads back.
    mut arr: json::JsonValue = json::JsonValue::new_array();
    arr.push(json::JsonValue::from_number(1e21));
    arr.push(json::JsonValue::from_number(0.000001));
    immut text: string = json::stringify(arr);
    test::assert_eq(text, "[1e+21,1e-06]", "stringify uses an exponent");
    immut back: json::JsonValue = json::parse(text) recover run {
        test::fail("a stringified document parses back");
        return 1;
    };
    test::assert_eq(back.at(0).num_val, 1e21, "1e+21 round trip");
    test::assert_eq(back.at(1).num_val, 0.000001, "1e-06 round trip");

    // An exponent with no digits is still malformed.
    test::assert(rejects("[1e]"), "'1e' is rejected");
    test::assert(rejects("[1e+]"), "'1e+' is rejected");
    test::assert(!rejects("[1E5]"), "'1E5' is accepted");
    return 0;
}

// A JSON number may have an exponent (RFC 8259: `1e10`, `2.5E-3`,
// `-1.5e+2`), and json::stringify writes one for a large or small number
// (`%g`: 1e+21, 1e-06). json::parse failed on every such number, so a value
// json::stringify wrote could not be read back: strings::parse_double
// rejected exponents (the header claimed only the value came out wrong).

import json;
import test;

// A `return` inside `recover run` returns from the enclosing function, so the
// failure check lives in its own helper.
fn rejects(text: string): bool {
    immut v: json::JsonValue = json::parse(text) recover run {
        return true;
    };
    return v.length() < 0;
}

fn main(): int {
    immut v: json::JsonValue = json::parse("[3e2, -1.5E-3, 1e+21, 2, 0.5e1]") recover run {
        test::fail("numbers with exponents are valid JSON");
        return 1;
    };
    test::assert_eq(v.length(), 5, "five numbers");
    test::assert_eq(v.at(0).num_val, 300.0, "3e2");
    test::assert_eq(v.at(1).num_val, -0.0015, "-1.5E-3");
    test::assert_eq(v.at(2).num_val, 1e21, "1e+21");
    test::assert_eq(v.at(4).num_val, 5.0, "0.5e1");

    // What stringify writes with an exponent reads back.
    mut arr: json::JsonValue = json::JsonValue.new_array();
    arr.push(json::JsonValue::from_number(1e21));
    arr.push(json::JsonValue::from_number(0.000001));
    immut text: string = json::stringify(arr);
    test::assert_eq(text, "[1e+21,1e-06]", "stringify uses an exponent");
    immut back: json::JsonValue = json::parse(text) recover run {
        test::fail("a stringified document parses back");
        return 1;
    };
    test::assert_eq(back.at(0).num_val, 1e21, "1e+21 round trip");
    test::assert_eq(back.at(1).num_val, 0.000001, "1e-06 round trip");

    // An exponent with no digits is still malformed.
    test::assert(rejects("[1e]"), "'1e' is rejected");
    test::assert(rejects("[1e+]"), "'1e+' is rejected");
    test::assert(!rejects("[1E5]"), "'1E5' is accepted");
    return 0;
}

