// FDN-001 (docs/planning/ROADMAP_v2.0.0.md, DEC-5): the other canonical
// "genuinely needs a nullable pointer" data structure, dynamically sized
// via `heap()` -- same proof as 05_dynamic_linked_list.tr, different shape
// (two nullable children, `random::random_int`-keyed instead of a fixed
// sequence). `random::random_int` is genuinely non-deterministic (it
// reseeds every call, lib/std/random/random.tr's own doc comment) but that
// is fine here: the property under test -- an in-order traversal of a BST
// is non-decreasing, and every inserted node is reachable -- holds for ANY
// key sequence, sorted or not, so the test needs no fixed expected values.
import random;
import test;
import io;

struct TreeNode {
    val: int,
    left: &?TreeNode,
    right: &?TreeNode
}

// Accumulates an in-order traversal's running verdict. Passed by `&T`
// (not by value) so recursive calls all mutate the SAME state -- there is
// no output-parameter/multi-return syntax in this language, so a struct
// reference is the idiomatic way one recursive walk reports back a result
// (the same shape `self`-mutating methods already rely on, LANG-002).
struct TraverseState {
    lastVal: int,
    hasLast: bool,
    isSorted: bool,
    count: int
}

fn makeNode(v: int): &TreeNode {
    mut n: TreeNode = TreeNode::default();
    n.val = v;
    return heap(n);
}

fn insert(root: &?TreeNode, n: &TreeNode): &?TreeNode {
    if (root == null) {
        return n;
    }
    if (n.val < root.val) {
        root.left = insert(root.left, n);
    } else {
        root.right = insert(root.right, n);
    }
    return root;
}

fn countNodes(root: &?TreeNode): int {
    if (root == null) {
        return 0;
    }
    return 1 + countNodes(root.left) + countNodes(root.right);
}

fn inorder(root: &?TreeNode, state: &TraverseState): void {
    if (root == null) {
        return;
    }
    inorder(root.left, state);
    if (state.hasLast && root.val < state.lastVal) {
        state.isSorted = False;
    }
    state.lastVal = root.val;
    state.hasLast = true;
    state.count = state.count + 1;
    inorder(root.right, state);
}

fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0;
    mut i: int = 0;
    while i < 64 {
        buf[i] = i * 3;
        i = i + 1;
    }
    mut total: int = 0;
    i = 0;
    while i < 64 {
        total = total + buf[i];
        i = i + 1;
    }
    test::assert(total == 6048, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn main(): int {
    immut n: int = 300;
    mut root: &?TreeNode = null;
    mut i: int = 0;
    while i < n {
        immut key: int = random::random_int(0, 1000000);
        root = insert(root, makeNode(key));
        i = i + 1;
    }

    test::assert(countNodes(root) == n, "all n randomly-keyed nodes are reachable");

    churn(24);
    gc_collect();
    churn(24);

    test::assert(countNodes(root) == n, "the whole tree survives a forced collection while retained");

    mut state: TraverseState = TraverseState::default();
    state.isSorted = true;
    inorder(root, &state);
    test::assert(state.count == n, "in-order traversal visits every node exactly once");
    test::assert(state.isSorted, "in-order traversal of a BST over random keys is non-decreasing");

    io::printline("39/06 PASS: heap()-allocated dynamic binary tree survives collection, in-order sorted");
    return 0;
}

// A payload may carry a reference the function was given, or a heap one:
// both outlive the frame (contrast fail_escape_error_payload.tr).

import test;

struct N { val: int, next: &?N }

error E1 {
    P(r: &N),
    Q
}

fn fail_with(p: &N): !int {
    return E1::P(p);
}

fn fail_with_heap(): !int {
    mut n: N = N::default();
    n.val = 9;
    return E1::P(heap(n));
}

fn payload_val(fail_heap: bool, p: &N): int {
    mut v: int = fail_with_heap() if (fail_heap else fail_with(p)) recover as err run {
        compare err {
            matches E1::P(r):
            return r.val;
            done
            otherwise:
            return -1;
        }
    };
    return v;
}

fn main(): int {
    mut n: N = N::default();
    n.val = 42;
    test::assert(payload_val(false, &n) == 42, "payload reference to the caller's object");
    test::assert(payload_val(true, &n) == 9, "payload reference to a heap object");
    return 0;
}

// A reference that is `&n` on one path and the heap on another is fine as
// long as it never reaches a sink: only an escape on some path is E086
// (fail_escape_return_mixed_paths.tr). Reassigned on every path before the
// return, it is fine too.

import test;

struct N { val: int, next: &?N }

fn read_either(c: bool): int {
    mut n: N = N{};
    n.val = 1;
    mut p: &N = heap(n);
    if (c) {
        p = &n;
    }
    return p.val;
}

fn reassigned(c: bool): &N {
    mut n: N = N::default();
    n.val = 7;
    mut p: &N = heap(n);
    if (c) {
        p = &n;
        p.val = 8;
    }
    p = heap(n);
    return p;
}

fn main(): int {
    test::assert(read_either(true) == 1, "stack path read locally");
    test::assert(read_either(false) == 1, "heap path read locally");
    test::assert(reassigned(true).val == 8, "reassigned before the return");
    return 0;
}

// INV-DEFER-2's other side: a deferred `recover` whose block does NOT jump out
// of the function (here it only records the failure; `!void` so it need not
// diverge) is fine, and runs when the block exits.
import test;

error E {
    Bad
}

struct Seen {
    n: int
}

fn Seen.new(): void {
    self.n = 0;
}

fn failing(): not void {
    return E::Bad;
}

fn g(s: &Seen): int {
    defer failing() recover run { s.n = s.n + 1; };
    return 1;
}

fn main(): int {
    mut s: Seen = Seen::new();
    test::assert(g(&s) == 1, "g returns its own value");
    test::assert(s.n == 1, "the deferred recover block ran");
    return 0;
}

// tests/41_gc/08_error_message_survives_collection.tr
// OVH-002 (docs/planning/OVERHAUL_REMAINING_WORK.md): `CodegenErrorVariantConstructWithMessage()`
// (src/codegen/CodegenCore.cpp) heap-allocates the `TurfErrorValue{tag, message}`
// struct a message-carrying error construction (`ErrorType::Variant(msg)`)
// produces, since the message is in general a runtime value. Before this
// fix that allocation was a bare `malloc()` -- never registered with the
// collector's block table, so `err.message`'s GC-heap `string` pointer,
// reachable ONLY through that unregistered block, had no root of its own.
// A collection between the error's construction and the point `err` is
// finally read (`recover as err run`'s own failure block, which runs
// ordinary user code -- exactly where a collection legitimately could
// happen) would sweep the message string, corrupting `err.message`.
//
// `makeError()` constructs the error in a deeper call frame than the one
// that later reads it (mirroring 01/02's own "deeper frame" discipline);
// the collection runs INSIDE `recover as err run`'s block, after `err` is
// bound but before its message is read -- precisely the window OVH-002's
// own testing scope names ("collect inside the `recover as err run`
// block, compare `err.message` to a freshly rebuilt expected string").
//
// `junk()` between the two collections allocates a few thousand throwaway
// strings (docs/planning/OVERHAUL_REMAINING_WORK.md §1's own guidance) so
// a freed block is actually REUSED with different content, not merely
// freed-but-still-readable-by-luck -- glibc's `free()` doesn't zero or
// scramble memory on its own, so a bug that fails to keep `message` rooted
// would otherwise still often read back correct-looking (stale, not yet
// overwritten) bytes and falsely appear to pass.

import strings;
import test;
import io;

error MyError {
    Bad
}

fn makeError(): !void {
    return MyError::Bad(strings::repeat("m", 40));
}

fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0;
    mut i: int = 0;
    while i < 64 {
        buf[i] = i * 17;
        i = i + 1;
    }
    mut sum: int = 0;
    i = 0;
    while i < 64 {
        sum = sum + buf[i];
        i = i + 1;
    }
    test::assert(sum == 34272, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn junk(n: int): void {
    mut i: int = 0;
    while i < n {
        strings::repeat("j", 40);
        i = i + 1;
    }
}

fn main(): int {
    // T is `void` here (§1.6 of docs/architecture/errors_and_recover.md):
    // the recover block is not required to diverge, so execution
    // continues normally afterward -- letting this test assert AND still
    // reach the PASS line below in the same run.
    makeError() recover as err run {
        churn(24);
        gc_collect();
        junk(2000);
        churn(24);
        gc_collect();

        const string expected = strings::repeat("m", 40);
        test::assert(err == MyError::Bad, "the error variant identity survives a forced collection");
        test::assert(strings::length(err.message) == 40, "err.message survives with correct length -- OVH-002's actual reproducer");
        test::assert(err.message == expected, "err.message content survives, compared against a freshly rebuilt expected string");
    };

    io::printline("41/08 PASS: a message-carrying error value's GC-heap message string is precisely traced through a forced collection");
    return 0;
}

// LEC-004: the parser reads `Name::Name(...)` at the top of a `matches` header
// as an error-variant pattern, because only the Resolver knows whether `Name` is
// an error type. When it is not, the header must mean what it always meant: a
// value pattern that CALLS a module function (legal against a string subject).
// `strings::to_upper("ab")` here is such a call, not a pattern.
import strings;
import test;

fn classify(s: string): int {
    compare s {
        matches strings::to_upper("ab":
        return 1;
        done
        matches strings::to_lower("CD"):
        return 2;
        done
        otherwise:
        return 3;
    }
}

fn main(): int {
    test::assert(classify("AB") == 1, "a module call in a header is still a value pattern");
    test::assert(classify("cd") == 2, "a second one");
    test::assert(classify("zz") == 3, "otherwise");
    return 0;
}

// LEC-004: the parser reads `Name::Name(...)` at the top of a `matches` header
// as an error-variant pattern, because only the Resolver knows whether `Name` is
// an error type. When it is not, the header must mean what it always meant: a
// value pattern that CALLS a module function (legal against a string subject).
// `strings::to_upper("ab")` here is such a call, not a pattern.
import strings;
import test;

fn classify(s: string): int {
    compare s {
        matches strings::to_upper("ab"):
        return 1;
        done
        matches strings::to_lower("CD"):
        return 2;
        break;
        otherwise:
        return 3;
    }
}

fn main(): int {
    test::assert(classify("AB") == 1, "a module call in a header is still a value pattern");
    test::assert(classify("cd") == 2, "a second one");
    test::assert(classify("zz") == 3, "otherwise");
    return 0;
}

// API lock, part 4: arrays. See 01_core_and_collections.tr for what this
// folder is.
import arrays;
import test;

fn double_it(int x): int {
    return x * 2;
}

fn index(i: int): int {
    return i;
}

fn main(): int {
    mut a: int[3] = arrays::fill(1);
    mut b: int[3] = arrays::generate(index);
    mut c: int[3] = arrays::reversed(b);
    mut d: int[3] = arrays::map(c, double_it);
    test::assert(a[0] == 1 && b[2] == 2 && c[0] == 2 && d[0] == 4, "arrays");
    return 0;
}

// Issue #260: a `T[]` parameter handed on to another function's `T[]`
// parameter. This used to pass the address of the stack slot that HELD the
// array pointer, so the second function read garbage -- `outer(x)` below
// returned 32, not 4. Now the slice (pointer and length) is passed as it is.
import test;

fn first(a: int[]): int {
    return a[0];
}

fn len(a: int[]): int {
    return a->length();
}

fn outer(a: int[]): int {
    return first(a);
}

fn outer_len(a: int[]): int {
    return len(a);
}

// Three levels, with a write at the bottom.
fn zero_first(a: int[]): void {
    a[0] = 0;
}

fn middle(a: int[]): void {
    zero_first(a);
}

fn top(a: int[]): void {
    middle(a);
}

fn main(): int {
    mut x: int[2] = [4, 5];
    test::assert(outer(x) == 4, "a forwarded slice still points at the caller's elements");
    test::assert(outer_len(x) == 2, "a forwarded slice keeps its length");

    mut y: int[3] = [9, 9, 9];
    top(y);
    test::assert(y[0] == 0, "a write three calls down reaches the caller's array");
    test::assert(y[1] == 9, "...and only the element written");
    return 0;
}

// A program's own function wins over a built-in of the same name. `heap`,
// `typeof` and the `gc_*` names are the compiler's bare intrinsics, but they
// are only consulted when NO declared function has the name; each of these used
// to be taken over by the built-in and crashed the compiler with "generated
// LLVM IR is invalid". `heap` in particular is a natural name for a user's
// priority queue.

import test;

fn heap(n: int): int {
    return n + 1;
}

fn typeof(n: int): int {
    return n + 2;
}

fn gc_alloc(n: int): int {
    return n + 3;
}

fn gc_alloc_zeroed(n: int): int {
    return n + 4;
}

fn gc_realloc(a: int, b: int): int {
    return a + b
}

fn gc_collect(): int {
    return 5;
}

fn gc_is_managed(n: int): bool {
    return n > 0;
}

fn gc_checked_free(n: int): int {
    return n + 6;
}

fn gc_pin(n: int): int {
    return n + 7;
}

fn gc_unpin(n: int): int {
    return n + 8;
}

fn main(): int {
    test::assert(heap(1) == 2, "own heap()");
    test::assert(typeof(1) == 3, "own typeof()");
    test::assert(gc_alloc(1) == 4, "own gc_alloc()");
    test::assert(gc_alloc_zeroed(1) == 5, "own gc_alloc_zeroed()");
    test::assert(gc_realloc(1, 2) == 3, "own gc_realloc()");
    test::assert(gc_collect() == 5, "own gc_collect()");
    test::assert(gc_is_managed(1), "own gc_is_managed()");
    test::assert(gc_checked_free(1) == 7, "own gc_checked_free()");
    test::assert(gc_pin(1) == 8, "own gc_pin()");
    test::assert(gc_unpin(1) == 9, "own gc_unpin()");
    return 0;
}

// LEC-009 (F-COLL-1): a struct holding a collection is copied by value, but
// the collection inside is a handle, so both copies of the struct name the
// same collection. `S::default()` gives the field its own empty collection
// (F-COLL-2), so even a struct that was never pushed to shares correctly.
import list::List;
import map::Map;
import test;

struct Registry {
    names: List<string>,
    ids: Map<string, int>,
    count: int
}

fn register(r: Registry, name: string): void {
    r.ids.put(name, r.names.length());
    r.names.push(name);
    r.count = r.count + 1;
}

fn main(): int {
    mut r: Registry = Registry::default();
    register(r, "a");
    register(r, "b");
    test::assert(r.names.length() == 2 && r.ids.get("b") == 1, "callee changes the shared collections");
    test::assert(r.count == 0, "the int field is still a copy");

    mut other: Registry = Registry::default();
    test::assert(other.names.size() == 0, "a second default has its own list");

    // Independent copy of the struct's contents.
    mut snapshot: Registry = Registry::default();
    snapshot.names = r.names.copy();
    r.names.push("c");
    test::assert(snapshot.names.length() == 2 && r.names.length() == 3, "copy() of a field");

    // Lists of lists: an element is a handle too.
    mut grid: List<List<int>> = List::default();
    mut row: List<int> = List::default();
    grid.push(row);
    grid[0].push(4);
    test::assert(grid[0].length() == 1 && grid[0][0] == 4, "grid[0].push lands");
    test::assert(row.length() == 1, "the pushed row is the same list");
    return 0;
}

// An array of structs that hold a `&U` is fine with an initializer, and an
// `&?U` field needs none: its elements start null (contrast
// fail_array_of_structs_holding_reference_without_initializer.tr).

import test;

struct U { v: int }

struct H {
    own: &U,
    k: int
}

struct M {
    maybe: &?U,
    k: int
}

fn main(): int {
    a := [H::default(), H::default()];
    test::assert(a[1].own.v == 0, "every element initialised");
    mut b: M[2];
    b[0] = M::default();
    test::assert(b[1].maybe == null, "a nullable field starts null");
    return 0;
}

// The `arrays` module builds fixed-size arrays. The length comes from the
// type the result is stored into (a declaration, an assignment, a parameter,
// a `return`) or from an array argument.

import arrays;
import test;

struct Point {
    int x,
    y: int
}

struct Holder {
    vals: int[3]
}

fn square(i: int): int {
    return i * i;
}

fn label(i: int): string {
    return "n" + (i to string);
}

fn four_nines(): int[4] {
    return arrays::fill(9);
}

fn ends(a: int[4]): int {
    return a[0] + a[3];
}

fn main(): int {
    mut zeros: int[1000] = arrays::fill(0);
    test::assert(zeros[0] == 0 && zeros[999] == 0, "1000 zeros");
    mut names: string[3] = arrays::fill("?");
    test::assert(names[2] == "?", "strings");
    mut flags: bool[2] = arrays::fill(true);
    test::assert(flags[0] && flags[1], "bools");
    mut halves: double[5] = arrays::fill(0.5);
    test::assert(halves[4] == 0.5, "doubles");
    mut p: Point = Point::default();
    p.x = 3;
    mut pts: Point[2] = arrays::fill(p);
    test::assert(pts[1].x == 3, "structs");

    mut row: int[3] = arrays::fill(1);
    mut grid: int[2][3] = arrays::fill(row);
    test::assert(grid[1][2] == 1, "rows of a 2-D array");

    zeros = arrays::fill(7);
    test::assert(zeros[500] == 7, "assignment");
    test::assert(four_nines()[3] == 9, "return");
    test::assert(ends(arrays::fill(2)) == 4, "argument");
    mut h: Holder = Holder::default();
    h.vals = arrays::fill(6);
    test::assert(h.vals[2] == 6, "field");

    mut squares: int[5] = arrays::generate(square);
    test::assert(squares[0] == 0 && squares[4] == 16, "generate");

    mut back: int[5] = arrays::reversed(squares);
    test::assert(back[0] == 16 && back[4] == 0, "reversed");
    test::assert(arrays::reversed(arrays::reversed(squares))[1] == 1, "reversed twice");

    mut texts: string[5] = arrays::map(squares, label);
    test::assert(texts[2] == "n4", "map to another type");
    return 0;
}
